"""Seating charts: students sorted by last name, in rows."""

from rosterkit.models import Student
from rosterkit.errors import ProjectError


# ---
def seat_rows(students, per_row):
    if per_row < 1 or not students:
        raise ProjectError("need students and seats")
    ordered = sorted(students, key=_sort_key)
    names = [item.display_name for item in ordered]
    return _format_rows(names, per_row)


def _sort_key(item):
    return (item.last_name, item.first_name)


def _format_rows(names, per_row):
    lines = []
    for start in range(0, len(names), per_row):
        row = " | ".join(names[start:start + per_row])
        lines.append(f"Row {start // per_row + 1}: {row}")
    return lines

